// ServerInterface represents all server handlers.
type ServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(w http.ResponseWriter, r *http.Request)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(w http.ResponseWriter, r *http.Request)
	// 超管读取子账号列表
	// (GET /v1/accounts)
	ListAccounts(w http.ResponseWriter, r *http.Request, params ListAccountsParams)
	// 超管创建子账号并标记强改
	// (POST /v1/accounts)
	CreateAccount(w http.ResponseWriter, r *http.Request)
	// 超管重置子账号初始口令
	// (POST /v1/accounts/{accountId}/password:reset)
	ResetAccountPassword(w http.ResponseWriter, r *http.Request, accountId Identifier)
	// 修改10项功能权限
	// (PUT /v1/accounts/{accountId}/permissions)
	SetAccountPermissions(w http.ResponseWriter, r *http.Request, accountId Identifier)
	// 停用/恢复/删除子账号
	// (PUT /v1/accounts/{accountId}/status)
	SetAccountStatus(w http.ResponseWriter, r *http.Request, accountId Identifier)
	// 按最新账号功能权限授权
	// (POST /v1/authorizations/check)
	CheckAuthorization(w http.ResponseWriter, r *http.Request)
	// 取得可恢复的数据屏障
	// (POST /v1/barriers)
	AcquireBarrier(w http.ResponseWriter, r *http.Request)
	// 释放屏障
	// (DELETE /v1/barriers/{barrierId})
	ReleaseBarrier(w http.ResponseWriter, r *http.Request, barrierId Identifier)
	// portal内部核对CSRF
	// (POST /v1/csrf:verify)
	VerifySessionCSRF(w http.ResponseWriter, r *http.Request)
	// 读自身后台偏好
	// (GET /v1/preferences)
	ReadPreferences(w http.ResponseWriter, r *http.Request)
	// 保存自身主题/语言/默认后台页
	// (PUT /v1/preferences)
	UpdatePreferences(w http.ResponseWriter, r *http.Request)
	// 决定后台显示首次注册或登录
	// (GET /v1/registration)
	ReadRegistrationState(w http.ResponseWriter, r *http.Request)
	// 首个注册账户原子成为唯一超管
	// (POST /v1/registration)
	RegisterFirstSuperadmin(w http.ResponseWriter, r *http.Request)
	// 读取当前账户
	// (GET /v1/self)
	ReadSelf(w http.ResponseWriter, r *http.Request)
	// 改口令并结束其他设备登录
	// (POST /v1/self/password:change)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// 读取自身登录设备
	// (GET /v1/sessions)
	ReadSessions(w http.ResponseWriter, r *http.Request, params ReadSessionsParams)
	// 账号名口令登录
	// (POST /v1/sessions)
	CreateSession(w http.ResponseWriter, r *http.Request)
	// 退出当前或指定自身登录
	// (DELETE /v1/sessions/{sessionId})
	RevokeSession(w http.ResponseWriter, r *http.Request, sessionId Identifier)
	// 内部透明轮换session
	// (POST /v1/sessions:refresh)
	RefreshSession(w http.ResponseWriter, r *http.Request)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(w http.ResponseWriter, r *http.Request)
	// 导出屏障水位的一致快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(w http.ResponseWriter, r *http.Request)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(w http.ResponseWriter, r *http.Request)
}

